const baseUrl = ($env.RS_CANONICAL_BASE_URL || 'https://rsperformance.online').replace(/\/$/, '');
const token = $env.N8N_API_TOKEN || $env.RS_API_TOKEN || '';
if (!String(token).trim()) {
  throw new Error('SEO Search Ops promoter: set RS_API_TOKEN or N8N_API_TOKEN in n8n environment (X-API-Token for hosting Search Ops API).');
}

return [
  {
    json: {
      queueType: 'micro_expansion',
      path: '/api/search-ops/opportunities?decision=micro_expansion&tier=tier_a&limit=4',
      baseUrl,
      token,
    },
  },
  {
    json: {
      queueType: 'new_support_page',
      path: '/api/search-ops/opportunities?decision=new_support_page&tier=tier_b&limit=4',
      baseUrl,
      token,
    },
  },
];

const seeds = $('Build Promotion Queues').all();
const fallbackBaseUrl = ($env.RS_CANONICAL_BASE_URL || 'https://rsperformance.online').replace(/\/$/, '');
const fallbackToken = $env.N8N_API_TOKEN || $env.RS_API_TOKEN || '';
const payloads = [];

for (const item of $input.all()) {
  const pairedIndex = typeof item.pairedItem?.item === 'number' ? item.pairedItem.item : 0;
  const seed = seeds[pairedIndex]?.json || {};
  const queueType = seed.queueType || item.json.queueType || 'unknown';
  const baseUrl = seed.baseUrl || item.json.baseUrl || fallbackBaseUrl;
  const token = seed.token || item.json.token || fallbackToken;
  const rows = Array.isArray(item.json.items) ? item.json.items : [];

  for (const row of rows) {
    payloads.push({
      json: {
        queueType,
        baseUrl,
        token,
        query: row.query,
        decision: row.route?.decision || 'reject',
        tier: row.score?.tier || 'out_of_band',
        target_path: row.route?.target_path || null,
        has_existing_target: Boolean(row.route?.target_path),
        intent: row.intent || 'unknown',
        estimated_chars: queueType === 'micro_expansion' ? 420 : 780,
        requires_title_rewrite: false,
        cannibalization_risk: queueType === 'micro_expansion' ? 'low' : 'medium',
      },
    });
  }
}

if (payloads.length === 0) {
  return [{ json: { queueType: 'empty', baseUrl: fallbackBaseUrl, token: fallbackToken, query: 'no-op', decision: 'reject', tier: 'out_of_band', skipPromotion: true } }];
}

return payloads;

const items = $input.all();
let ready = 0;
let review = 0;
const lines = [];

for (const item of items) {
  const status = item.json.status || 'idle';
  const query = item.json.query || item.json.body?.query || item.json.draft?.headline || 'n/a';

  if (status === 'ready_for_apply') {
    ready += 1;
  }
  if (status === 'review_required') {
    review += 1;
  }

  lines.push(`${status}: ${query}`);
}

return [{
  json: {
    ready,
    review,
    total: items.length,
    checkedAt: new Date().toISOString(),
    report: lines.slice(0, 8).join('\n') || 'No SEO promotion actions were executed.',
  },
}];
